1	export type Item = { type: string; cursed?: boolean; enchantment?: number };
2	export type Step = { items: Item[] };
3	export type Scenario = { steps: Step[] };
4	export type Result = { premium: number };
5	export type ScenarioOutcome = { results: Result[] };
6	
7	const BASE_PREMIUMS: Record<string, number> = {
8	  sword: 100,
9	  amulet: 60,
10	  staff: 80,
11	  potion: 40,
12	  rune: 25,
13	  moonstone: 25,
14	};
15	
16	const FIRST_INSURANCE_SURCHARGE = 1.1;
17	const PROCESSING_FEE = 5;
18	
19	// Guards against binary-float artifacts (e.g. 52.800000000000004) tipping an
20	// exact value over a whole-gold boundary and inflating the premium by 1 G.
21	const FLOAT_ARTIFACT_PRECISION = 6;
22	
23	const roundUpToWholeGold = (amount: number): number =>
24	  Math.ceil(Number(amount.toFixed(FLOAT_ARTIFACT_PRECISION)));
25	
26	// Multipliers on the base premium, not amounts added to it.
27	const CURSED_RISK_FACTOR = 1.5;
28	const HIGH_ENCHANTMENT_RISK_FACTOR = 1.3;
29	const NO_ADDED_RISK = 1;
30	
31	const HIGH_ENCHANTMENT_LEVEL = 5;
32	
33	const isHighlyEnchanted = (item: Item): boolean =>
34	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
35	
36	// Risks compound: an item that is both cursed and highly enchanted carries
37	// both factors.
38	const riskFactorOf = (item: Item): number =>
39	  (item.cursed ? CURSED_RISK_FACTOR : NO_ADDED_RISK) *
40	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_RISK_FACTOR : NO_ADDED_RISK);
41	
42	// The price-list value adjusted for the item's own risk — not the bare
43	// BASE_PREMIUMS figure.
44	const riskAdjustedPremiumOf = (item: Item): number =>
45	  BASE_PREMIUMS[item.type] * riskFactorOf(item);
46	
47	const BUILDING_BLOCK_SIZE = 3;
48	const BUILDING_BLOCK_PREMIUM = 60;
49	
50	const areAlike = (items: Item[]): boolean =>
51	  items.every((item) => item.type === items[0].type);
52	
53	const sumOfPremiums = (items: Item[]): number =>
54	  items.reduce((total, item) => total + riskAdjustedPremiumOf(item), 0);
55	
56	// An unalike list forms no blocks at all, however many items it holds.
57	const buildingBlockCountOf = (items: Item[]): number =>
58	  areAlike(items) ? Math.floor(items.length / BUILDING_BLOCK_SIZE) : 0;
59	
60	// Alike items group into building blocks priced below the sum of their members'
61	// individual premiums; everything left over prices individually.
62	const blockPricedTotalOf = (items: Item[]): number => {
63	  const blocks = buildingBlockCountOf(items);
64	  const looseItems = items.slice(blocks * BUILDING_BLOCK_SIZE);
65	
66	  return blocks * BUILDING_BLOCK_PREMIUM + sumOfPremiums(looseItems);
67	};
68	
69	const premiumFor = (step: Step): number =>
70	  roundUpToWholeGold(blockPricedTotalOf(step.items) * FIRST_INSURANCE_SURCHARGE) +
71	  PROCESSING_FEE;
72	
73	export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
74	  results: [{ premium: premiumFor(scenario.steps[0]) }],
75	});
