// The fee is a flat charge on top of the rounded premium, so it sits outside
// the rounding rather than being rounded along with it.
const premiumFor = (step: Step): number => {
  const insuredValue = blockPricedTotalOf(step.items) * FIRST_INSURANCE_SURCHARGE;

  return roundUpToWholeGold(insuredValue) + PROCESSING_FEE;
};
